    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav-menu a {
    font-weight: 500;
    padding: var(--spacing-xs) var(--spacing-sm);
    border-bottom: 2px solid transparent;
    transition: var(--transition);
    display: inline-block;
}

.nav-menu a:hover {
    border-bottom-color: var(--primary-color);
    text-decoration: none;
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
    align-items: center;
}

.icon-btn {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1.5rem;
    padding: var(--spacing-xs);
    position: relative;
    transition: var(--transition);
    display: flex;
    align-items: center;
    justify-content: center;
}

.icon-btn:hover {
    transform: scale(1.1);
}

.icon-btn:focus-visible {
    outline: 2px solid var(--primary-color);
    outline-offset: 2px;
}

.cart-count {
    position: absolute;
    top: -5px;
    right: -5px;
    background: var(--accent-color);
    color: var(--bg-white);
    font-size: 0.75rem;
    font-weight: bold;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* ==================== */
/* Hero Section         */
/* ==================== */
.hero {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--secondary-color) 100%);
    color: var(--bg-white);
    padding: 6rem var(--spacing-md);
    text-align: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content h2 {
    font-size: 3rem;
    margin-bottom: var(--spacing-md);
}

.hero-content p {
    font-size: 1.25rem;
    margin-bottom: var(--spacing-lg);
    color: rgba(255, 255, 255, 0.9);
}

/* ==================== */
/* Sections             */
/* ==================== */
.featured-section,
.deals-section,
.editorial-section {
    padding: var(--spacing-xl) var(--spacing-md);
}

.featured-section {
    background: var(--bg-white);
}

.deals-section {
    background: var(--bg-light);
}

.editorial-section {
    background: var(--bg-white);
}

.section-title {
    text-align: center;
    margin-bottom: var(--spacing-xl);
    font-size: 2rem;
}

/* ==================== */
/* Products Grid        */
/* ==================== */
.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.product-card {
    background: var(--bg-white);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-card:focus-within {
    box-shadow: var(--shadow-lg);
    outline: 2px solid var(--primary-color);
    outline-offset: 0;
}

.product-image {
    width: 100%;
    height: 200px;
    background-size: cover;
    background-position: center;
    position: relative;
}

.badge {
    position: absolute;
    top: var(--spacing-sm);
    right: var(--spacing-sm);
    background: var(--accent-color);
    color: var(--bg-white);
    padding: 0.25rem 0.75rem;
    border-radius: var(--radius-md);
    font-size: 0.75rem;
    font-weight: bold;
    text-transform: uppercase;
}

.product-info {
    padding: var(--spacing-md);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.product-info h3 {
    margin-bottom: var(--spacing-sm);
}

.product-info h3 a {
    color: var(--text-dark);
}

.product-category {
    font-size: 0.875rem;
    color: var(--text-light);
    margin-bottom: var(--spacing-sm);
}

.rating {
    margin-bottom: var(--spacing-sm);
    font-size: 1rem;
    letter-spacing: 0.05em;
}

.product-footer {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-top: auto;
    padding-top: var(--spacing-md);
    border-top: 1px solid var(--border-color);
}

.price {
    font-weight: bold;
    font-size: 1.125rem;
    color: var(--primary-color);
}

.original-price {
    text-decoration: line-through;
    color: var(--text-light);
    margin-right: var(--spacing-xs);
    font-weight: normal;
}

/* ==================== */
/* Deals Grid           */
/* ==================== */
.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
    gap: var(--spacing-lg);
}

.deal-card {
    border-radius: var(--radius-lg);
    overflow: hidden;
    transition: var(--transition);
}

.deal-card:hover {
    transform: scale(1.02);
    box-shadow: var(--shadow-lg);
}

.deal-card:focus-within {
    outline: 2px solid var(--text-dark);
    outline-offset: 0;
}

.deal-content {
    padding: var(--spacing-lg);
    color: var(--bg-white);
    text-align: center;
    display: flex;
    flex-direction: column;
    justify-content: center;
    min-height: 250px;
}

.deal-content h3 {
    margin-bottom: var(--spacing-sm);
    font-size: 1.5rem;
    color: var(--bg-white);
}

.deal-discount {
    font-size: 2rem;
    font-weight: bold;
    margin-bottom: var(--spacing-sm);
    color: var(--bg-white);
}

.deal-description {
    font-size: 0.95rem;
    margin-bottom: var(--spacing-md);
    color: rgba(255, 255, 255, 0.95);
}

/* ==================== */
/* Editorial Grid       */
/* ==================== */
.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--spacing-lg);
}

.editorial-card {
    border-radius: var(--radius-lg);
    overflow: hidden;
    background: var(--bg-white);
    border: 1px solid var(--border-color);
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.editorial-card:focus-within {
    outline: 2px solid var(--primary-color);
    outline-offset: 0;
}

.editorial-image {
    width: 100%;
    height: 250px;
    background-size: cover;
    background-position: center;
}

.editorial-content {
    padding: var(--spacing-md);
    flex: 1;
    display: flex;
    flex-direction: column;
}

.editorial-category {
    display: inline-block;
    background: var(--bg-light);
    color: var(--primary-color);
    padding: 0.25rem 0.75rem;
    border-radius: var(--radius-sm);
    font-size: 0.75rem;
    font-weight: bold;
    text-transform: uppercase;
    margin-bottom: var(--spacing-sm);
    width: fit-content;
}

.editorial-content h3 {
    margin-bottom: var(--spacing-sm);
}

.editorial-content h3 a {
    color: var(--text-dark);
}

.editorial-content p {
    flex: 1;
    margin-bottom: var(--spacing-md);
}

.read-more {
    font-weight: 600;
    color: var(--primary-color);
    display: inline-block;
}

.read-more:hover {
    color: var(--primary-dark);
}

/* ==================== */
/* Newsletter Section   */
/* ==================== */
.newsletter-section {
    background: linear-gradient(135deg, var(--primary-color) 0%, var(--secondary-color) 100%);
    color: var(--bg-white);
    padding: var(--spacing-xl) var(--spacing-md);
    text-align: center;
}

.newsletter-content h2 {
    color: var(--bg-white);
    margin-bottom: var(--spacing-md);
}

.newsletter-content p {
