    .editorial-grid {
        grid-template-columns: 1fr;
        gap: var(--spacing-md);
    }

    .deal-content {
        min-height: 200px;
        padding: var(--spacing-md);
    }

    .footer-grid {
        grid-template-columns: 1fr;
    }
}

