newsletterForm.addEventListener('submit', (e) => {
    e.preventDefault();

    const email = document.getElementById('email').value;

    // Simulate submission
    newsletterForm.style.opacity = '0.6';
    newsletterForm.style.pointerEvents = 'none';

    setTimeout(() => {
        // Success message
        newsletterMessage.textContent = `✓ Thanks for subscribing, ${email}!`;
        newsletterMessage.style.color = '#43e97b';

        // Reset form
        newsletterForm.reset();
        newsletterForm.style.opacity = '1';
        newsletterForm.style.pointerEvents = 'auto';

        // Clear message after 5 seconds
        setTimeout(() => {
            newsletterMessage.textContent = '';
        }, 5000);
    }, 1000);
});

// ============================
// Shop Now Button
// ============================
document.querySelector('.hero .btn-primary').addEventListener('click', () => {
    document.getElementById('featured').scrollIntoView({ behavior: 'smooth' });
});

// ============================
// Browse Deals & Shop Buttons
// ============================
document.querySelectorAll('.deal-card .btn-secondary').forEach((button, index) => {
    button.addEventListener('click', () => {
        const dealCard = button.closest('.deal-card');
        const dealTitle = dealCard.querySelector('h3').textContent;
        alert(`Navigating to ${dealTitle} section...`);
    });
});

// ============================
// Product Card Keyboard Navigation
// ============================
document.querySelectorAll('.product-card').forEach(card => {
    card.addEventListener('keydown', (e) => {
        const cards = Array.from(document.querySelectorAll('.product-card'));
        const currentIndex = cards.indexOf(card);

        if (e.key === 'ArrowRight') {
            e.preventDefault();
            const nextCard = cards[currentIndex + 1];
            if (nextCard) {
                nextCard.querySelector('a').focus();
            }
        } else if (e.key === 'ArrowLeft') {
            e.preventDefault();
            const prevCard = cards[currentIndex - 1];
            if (prevCard) {
                prevCard.querySelector('a').focus();
            }
        }
    });
});

// ============================
// Cart Icon Interaction
