const cartButton = document.querySelector('[aria-label="View shopping cart"]');

cartButton.addEventListener('click', () => {
    if (cart.length === 0) {
        alert('Your cart is empty');
    } else {
        let cartSummary = 'Items in cart:\n\n';
        cart.forEach((item, index) => {
            cartSummary += `${index + 1}. ${item.name} - ${item.price}\n`;
        });
        alert(cartSummary);
    }
});

// ============================
